-- Forward correction: inquiry lists always use the public summary projection.
-- Internal notes, actor identifiers, and status history remain detail-only data.

begin;

create or replace function public.hotel_inquiry_read_v1(p_company_id uuid,p_branch_id uuid,p_inquiry_id uuid,p_query jsonb,p_session_token text) returns table(command_status text,result_snapshot jsonb) language plpgsql volatile security definer set search_path=pg_catalog as $f$
declare actor record;internal boolean;page_no int:=greatest(coalesce((p_query->>'page')::int,1),1);page_size int:=least(greatest(coalesce((p_query->>'pageSize')::int,20),1),100);total_count int;
begin if p_query->>'mode'='SETTINGS'then select*into actor from public.hotel_inquiry_actor_v1(p_company_id,p_branch_id,p_session_token,'HOTEL_INQUIRY_SETTINGS');if not found then return query select'FORBIDDEN',null::jsonb;return;end if;return query select'OK',jsonb_build_object('contact',(select jsonb_build_object('phone',c.phone,'email',c.email,'operatingHours',c.operating_hours,'version',c.version)from public.hotel_inquiry_contacts c where c.company_id=p_company_id and c.branch_id=p_branch_id),'routes',coalesce((select jsonb_agg(jsonb_build_object('categoryCode',cat.code,'categoryName',cat.name,'groupId',r.group_id,'groupName',g.name,'active',coalesce(r.active,false),'version',coalesce(r.version,0))order by cat.name,cat.code)from public.hotel_inquiry_categories cat left join public.hotel_inquiry_routes r on r.company_id=cat.company_id and r.branch_id=p_branch_id and r.category_code=cat.code left join public.user_groups g on g.company_id=r.company_id and g.id=r.group_id where cat.company_id=p_company_id and cat.status='ACTIVE'),'[]'::jsonb),'groups',coalesce((select jsonb_agg(jsonb_build_object('id',g.id,'name',g.name)order by g.name,g.id)from public.user_groups g where g.company_id=p_company_id and g.status='ACTIVE'),'[]'::jsonb));return;end if;select * into actor from public.hotel_inquiry_actor_v1(p_company_id,p_branch_id,p_session_token,'HOTEL_INQUIRY_READ');internal:=found;if not internal then select * into actor from public.hotel_inquiry_actor_v1(p_company_id,p_branch_id,p_session_token,'HOTEL_OWNER_INQUIRY_READ');end if;if not found then return query select'FORBIDDEN',null::jsonb;return;end if;if p_query->>'mode'='CONTACT'then return query select'OK',jsonb_build_object('contact',jsonb_build_object('phone',c.phone,'email',c.email,'operatingHours',c.operating_hours,'version',c.version))from public.hotel_inquiry_contacts c where c.company_id=p_company_id and c.branch_id=p_branch_id;if not found then return query select'NOT_FOUND',null::jsonb;end if;return;end if;if p_inquiry_id is not null then if not internal and not public.hotel_inquiry_owner_can_read_v1(p_company_id,p_branch_id,p_inquiry_id,actor.user_id)then return query select'NOT_FOUND',null::jsonb;return;end if;return query select case when public.hotel_inquiry_snapshot_v1(p_company_id,p_branch_id,p_inquiry_id,internal)is null then'NOT_FOUND'else'OK'end,public.hotel_inquiry_snapshot_v1(p_company_id,p_branch_id,p_inquiry_id,internal);return;end if;select count(*)into total_count from public.hotel_inquiries i where i.company_id=p_company_id and i.branch_id=p_branch_id and(internal or public.hotel_inquiry_owner_can_read_v1(p_company_id,p_branch_id,i.id,actor.user_id))and(p_query->>'status'is null or i.status=p_query->>'status')and(p_query->>'categoryCode'is null or i.category_code=p_query->>'categoryCode');return query select'OK',jsonb_build_object('inquiries',coalesce((select jsonb_agg(public.hotel_inquiry_snapshot_v1(p_company_id,p_branch_id,x.id,false)order by x.updated_at desc,x.id)from(select i.id,i.updated_at from public.hotel_inquiries i where i.company_id=p_company_id and i.branch_id=p_branch_id and(internal or public.hotel_inquiry_owner_can_read_v1(p_company_id,p_branch_id,i.id,actor.user_id))and(p_query->>'status'is null or i.status=p_query->>'status')and(p_query->>'categoryCode'is null or i.category_code=p_query->>'categoryCode')order by i.updated_at desc,i.id offset(page_no-1)*page_size limit page_size)x),'[]'::jsonb),'pagination',jsonb_build_object('page',page_no,'pageSize',page_size,'total',total_count),'notifications',coalesce((select jsonb_agg(jsonb_build_object('id',n.id,'inquiryId',n.inquiry_id,'title',i.title,'eventCode',n.event_code,'createdAt',to_char(n.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'readAt',case when n.read_at is null then null else to_char(n.read_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')end)order by n.created_at desc,n.id)from(select n.* from public.hotel_inquiry_notifications n where n.company_id=p_company_id and n.branch_id=p_branch_id and n.recipient_user_id=actor.user_id order by n.created_at desc,n.id limit 100)n join public.hotel_inquiries i on i.company_id=n.company_id and i.branch_id=n.branch_id and i.id=n.inquiry_id),'[]'::jsonb));exception when invalid_text_representation then return query select'NOT_FOUND',null::jsonb;end $f$;

revoke all on function public.hotel_inquiry_read_v1(uuid,uuid,uuid,jsonb,text) from public;

insert into public.schema_migrations (version)
values ('0055_hotel_inquiry_list_projection_correction')
on conflict (version) do nothing;

commit;
